cssCode:
.typewriter {
  font-family: monospace;
  font-size: 1.6rem;
  color: #06b6d4;
  border-right: 2px solid #06b6d4;
  white-space: nowrap;
  overflow: hidden;
  animation:
    typing 3s steps(20) infinite alternate,
    blink 0.7s step-end infinite;
}
@keyframes typing {
  from { width: 0; }
  to   { width: 100%; }
}
@keyframes blink {
  50% { border-color: transparent; }
}

